HISTORY_VERSION = "2026-10-08-weekly-plus-months"



def _load_embedded_history() -> None:
    import base64, gzip
    if DB.exists():
        DB.unlink()
    conn = sqlite3.connect(DB)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS weeks (
            id INTEGER PRIMARY KEY,
            saved_at TEXT,
            inventory_file TEXT,
            sales_file TEXT,
            vehicle_count INTEGER,
            rows_json TEXT,
            is_current INTEGER
        )
        """
    )
    weeks = json.loads(gzip.decompress(base64.b64decode(HISTORY_B64)))
    conn.execute("DELETE FROM weeks")
    for item in weeks:
        conn.execute(
            "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, ?)",
            (item["saved_at"], item["inventory_file"], item["sales_file"], item["vehicle_count"], json.dumps(item["rows"]), item["is_current"]),
        )
    _stamp(conn)
    conn.commit()
    conn.close()


def _stamp(conn: sqlite3.Connection) -> None:
    conn.execute("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT)")
    conn.execute(
        "INSERT OR REPLACE INTO meta (key, value) VALUES ('history_version', ?)",
        (HISTORY_VERSION,),
    )


def _seed_is_current() -> bool:
    if not DB.exists():
        return False
    try:
        conn = sqlite3.connect(DB)
        row = conn.execute("SELECT value FROM meta WHERE key = 'history_version'").fetchone()
        conn.close()
    except sqlite3.Error:
        return False
    return bool(row and row[0] == HISTORY_VERSION)


def connect() -> sqlite3.Connection:
    DATA.mkdir(parents=True, exist_ok=True)
    if not _seed_is_current():
        _load_embedded_history()
    conn = sqlite3.connect(DB)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS weeks (
            id INTEGER PRIMARY KEY,
            saved_at TEXT,
            inventory_file TEXT,
            sales_file TEXT,
            vehicle_count INTEGER,
            rows_json TEXT,
            is_current INTEGER
        )
        """
    )
    _stamp(conn)
    conn.commit()
    _import_old_json(conn)
    ensure_month_summaries(conn)
    return conn


def _import_old_json(conn: sqlite3.Connection) -> None:
    if conn.execute("SELECT COUNT(*) FROM weeks").fetchone()[0]:
        return
    current = DATA / "current.json"
    archive = DATA / "archive"
    if current.exists():
        payload = json.loads(current.read_text())
        conn.execute(
            "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 1)",
            (
                payload.get("saved_at"),
                payload.get("inventory_file"),
                payload.get("sales_file"),
                payload.get("vehicle_count") or len(payload.get("rows") or []),
                json.dumps(payload.get("rows") or []),
            ),
        )
    if archive.exists():
        for path in sorted(archive.glob("*.json")):
            payload = json.loads(path.read_text())
            conn.execute(
                "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 0)",
                (
                    payload.get("saved_at"),
                    payload.get("inventory_file"),
                    payload.get("sales_file"),
                    payload.get("vehicle_count") or len(payload.get("rows") or []),
                    json.dumps(payload.get("rows") or []),
                ),
            )
    conn.commit()


def _payload(row) -> dict:
    return {
        "id": str(row[0]),
        "saved_at": row[1],
        "inventory_file": row[2],
        "sales_file": row[3],
        "vehicle_count": row[4],
        "rows": json.loads(row[5] or "[]"),
    }


def current_list() -> dict | None:
    conn = connect()
    row = conn.execute(
        "SELECT id, saved_at, inventory_file, sales_file, vehicle_count, rows_json FROM weeks WHERE is_current = 1 ORDER BY id DESC LIMIT 1"
    ).fetchone()
    conn.close()
    return _payload(row) if row else None


def archived_lists() -> list[dict]:
    conn = connect()
    rows = conn.execute(
        "SELECT id, saved_at, inventory_file, sales_file, vehicle_count, rows_json FROM weeks WHERE is_current = 0 ORDER BY saved_at DESC, id DESC"
    ).fetchall()
    conn.close()
    return [_payload(row) for row in rows]


def ensure_otc_table(conn: sqlite3.Connection) -> None:
    conn.execute("CREATE TABLE IF NOT EXISTS otc_months (label TEXT PRIMARY KEY, rows_json TEXT)")
    if conn.execute("SELECT COUNT(*) FROM otc_months").fetchone()[0]:
        return
    for label, rows in OTC_MONTHS.items():
        if rows:
            conn.execute("INSERT INTO otc_months (label, rows_json) VALUES (?, ?)", (label, json.dumps(rows)))
    conn.commit()


def save_otc_upload(raw: bytes, filename: str) -> list[str]:
    import re
    from io import BytesIO
    import pandas as pd

    book = pd.ExcelFile(BytesIO(raw))
    saved = []
    conn = connect()
    ensure_otc_table(conn)
    for sheet in book.sheet_names:
        if not re.match(r"^[A-Za-z]+ \d{4}$", sheet.strip()):
            continue
        frame = pd.read_excel(book, sheet, header=1)
        if frame.shape[1] < 6:
            continue
        frame = frame.iloc[:, :7]
        frame.columns = ["date", "stock", "year", "make", "model", "rep", "notes"]
        rows = []
        for rec in frame.to_dict(orient="records"):
            stock = re.sub(r"\s+", "", str(rec.get("stock") or "")).upper()
            if not stock or stock in {"NAN", "STOCK#", "STOCK"}:
                continue
            raw_date = str(rec.get("date") or "").strip()
            sale = ""
            for fmt in ("%m.%d.%Y", "%m/%d/%Y", "%Y-%m-%d"):
                try:
                    sale = datetime.strptime(raw_date, fmt).strftime("%Y-%m-%d")
                    break
                except ValueError:
                    pass
            rows.append({
                "sale_date": sale,
                "stock": stock,
                "year": rec.get("year"),
                "make": str(rec.get("make") or "").strip(),
                "model": str(rec.get("model") or "").strip(),
                "salesperson": str(rec.get("rep") or "").strip(),
            })
        if not rows:
            continue
        conn.execute("INSERT OR REPLACE INTO otc_months (label, rows_json) VALUES (?, ?)", (sheet.strip(), json.dumps(rows)))
        saved.append(f"{sheet.strip()} ({len(rows)})")
    conn.commit()
    ensure_month_summaries(conn)
    conn.close()
    return saved
    """OTC month sheets are the master list. Weekly rows fill in price and gross, duplicates dropped."""
    from sold_list import salesperson_name

    weeks = conn.execute(
        """
        SELECT saved_at, inventory_file, sales_file, rows_json
        FROM weeks
        WHERE inventory_file LIKE '%SOLD LIST%' AND inventory_file NOT LIKE '%summary%'
        """
    ).fetchall()
    weekly_by_stock: dict[str, tuple] = {}
    week_months = set()
    for saved_at, _inventory_file, sales_file, rows_json in weeks:
        week_months.add(saved_at[:7])
        for row in json.loads(rows_json or "[]"):
            stock = str(row.get("stock") or "").strip().upper()
            if not stock:
                continue
            prev = weekly_by_stock.get(stock)
            if prev is None or saved_at >= prev[0]:
                weekly_by_stock[stock] = (saved_at, row, sales_file)
    conn.execute("DELETE FROM weeks WHERE inventory_file LIKE '%summary%'")
    ensure_otc_table(conn)
    stored = conn.execute("SELECT label, rows_json FROM otc_months").fetchall()
    months = {label: json.loads(rows_json) for label, rows_json in stored} or OTC_MONTHS
    for label, otc_rows in months.items():
        if not otc_rows:
            continue
        month = datetime.strptime(label, "%B %Y").strftime("%Y-%m")
        year, mon = int(month[:4]), int(month[5:7])
        next_month = f"{year + 1}-01" if mon == 12 else f"{year}-{mon + 1:02d}"
        later = [saved_at for saved_at, *_ in weeks if saved_at[:7] >= next_month]
        if later:
            stamp = (datetime.fromisoformat(min(later)[:19]) - timedelta(seconds=1)).isoformat(timespec="seconds")
        else:
            stamp = f"{month}-31T23:59:59" if mon in {1, 3, 5, 7, 8, 10, 12} else f"{month}-30T23:59:59"
        seen = set()
        rows = []
        for otc in otc_rows:
            stock = str(otc.get("stock") or "").strip().upper()
            if not stock or stock in seen:
                continue
            seen.add(stock)
            weekly = weekly_by_stock.get(stock)
            base = dict(weekly[1]) if weekly else {
                "stock": stock,
                "vin": "",
                "year": otc.get("year"),
                "make": otc.get("make") or "",
                "model": otc.get("model") or "",
                "trim": "",
                "type": "",
                "mileage": None,
                "exterior": "",
                "interior": "",
                "web_price": None,
                "retail": None,
                "age": None,
                "matched": False,
                "comm": None,
                "house": None,
                "finance": None,
            }
            base["stock"] = stock
            base["sale_date"] = otc.get("sale_date") or base.get("sale_date") or ""
            base["salesperson"] = salesperson_name(otc.get("salesperson") or base.get("salesperson"))
            if otc.get("make"):
                base["make"] = str(otc["make"]).title()
            if otc.get("model"):
                base["model"] = str(otc["model"]).title()
            rows.append(base)
        rows.sort(key=lambda row: (str(row.get("make") or "").casefold(), str(row.get("model") or "").casefold(), str(row.get("stock") or "")))
        conn.execute(
            "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 0)",
            (stamp, f"SUPER HELPFUL SOLD LIST 2026 / {label} summary", "OTC month plus weekly gross", len(rows), json.dumps(rows)),
        )
    conn.commit()


def publish(rows: list[dict], inventory_file: str, sales_file: str) -> dict:
    saved_at = datetime.now().isoformat(timespec="seconds")
    conn = connect()
    conn.execute("UPDATE weeks SET is_current = 0 WHERE is_current = 1")
    conn.execute(
        "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 1)",
        (saved_at, inventory_file, sales_file, len(rows), json.dumps(rows)),
    )
    conn.commit()
    ensure_month_summaries(conn)
    conn.close()
    return {
        "saved_at": saved_at,
        "inventory_file": inventory_file,
        "sales_file": sales_file,
        "vehicle_count": len(rows),
        "rows": rows,
    }
def ensure_month_summaries(conn: sqlite3.Connection) -> None:
    """OTC month sheets are the master list. Weekly rows fill in price and gross, duplicates dropped."""
    weeks = conn.execute(
        """
        SELECT saved_at, inventory_file, sales_file, rows_json
        FROM weeks
        WHERE inventory_file LIKE '%SOLD LIST%' AND inventory_file NOT LIKE '%summary%'
        """
    ).fetchall()
    weekly_by_stock: dict[str, tuple] = {}
    week_months = set()
    for saved_at, _inventory_file, sales_file, rows_json in weeks:
        week_months.add(saved_at[:7])
        for row in json.loads(rows_json or "[]"):
            stock = str(row.get("stock") or "").strip().upper()
            if not stock:
                continue
            prev = weekly_by_stock.get(stock)
            if prev is None or saved_at >= prev[0]:
                weekly_by_stock[stock] = (saved_at, row, sales_file)
    conn.execute("DELETE FROM weeks WHERE inventory_file LIKE '%summary%'")
    ensure_otc_table(conn)
    stored = conn.execute("SELECT label, rows_json FROM otc_months").fetchall()
    months = {label: json.loads(rows_json) for label, rows_json in stored} or OTC_MONTHS
    for label, otc_rows in months.items():
        if not otc_rows:
            continue
        month = datetime.strptime(label, "%B %Y").strftime("%Y-%m")
        year, mon = int(month[:4]), int(month[5:7])
        next_month = f"{year + 1}-01" if mon == 12 else f"{year}-{mon + 1:02d}"
        later = [saved_at for saved_at, *_ in weeks if saved_at[:7] >= next_month]
        if later:
            stamp = (datetime.fromisoformat(min(later)[:19]) - timedelta(seconds=1)).isoformat(timespec="seconds")
        else:
            stamp = f"{month}-31T23:59:59" if mon in {1, 3, 5, 7, 8, 10, 12} else f"{month}-30T23:59:59"
        seen = set()
        rows = []
        for otc in otc_rows:
            stock = str(otc.get("stock") or "").strip().upper()
            if not stock or stock in seen:
                continue
            seen.add(stock)
            weekly = weekly_by_stock.get(stock)
            base = dict(weekly[1]) if weekly else {
                "stock": stock,
                "vin": "",
                "year": otc.get("year"),
                "make": otc.get("make") or "",
                "model": otc.get("model") or "",
                "trim": "",
                "type": "",
                "mileage": None,
                "exterior": "",
                "interior": "",
                "web_price": None,
                "retail": None,
                "age": None,
                "matched": False,
                "comm": None,
                "house": None,
                "finance": None,
            }
            base["stock"] = stock
            base["sale_date"] = otc.get("sale_date") or base.get("sale_date") or ""
            base["salesperson"] = salesperson_name(otc.get("salesperson") or base.get("salesperson"))
            if otc.get("make"):
                base["make"] = str(otc["make"]).title()
            if otc.get("model"):
                base["model"] = str(otc["model"]).title()
            rows.append(base)
        rows.sort(key=lambda row: (str(row.get("make") or "").casefold(), str(row.get("model") or "").casefold(), str(row.get("stock") or "")))
        conn.execute(
            "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 0)",
            (stamp, f"SUPER HELPFUL SOLD LIST 2026 / {label} summary", "OTC month plus weekly gross", len(rows), json.dumps(rows)),
        )
    conn.commit()


def publish(rows: list[dict], inventory_file: str, sales_file: str) -> dict:
    saved_at = datetime.now().isoformat(timespec="seconds")
    conn = connect()
    conn.execute("UPDATE weeks SET is_current = 0 WHERE is_current = 1")
    conn.execute(
        "INSERT INTO weeks (saved_at, inventory_file, sales_file, vehicle_count, rows_json, is_current) VALUES (?, ?, ?, ?, ?, 1)",
        (saved_at, inventory_file, sales_file, len(rows), json.dumps(rows)),
    )
    conn.commit()
    ensure_month_summaries(conn)
    conn.close()
    return {
        "saved_at": saved_at,
        "inventory_file": inventory_file,
        "sales_file": sales_file,
        "vehicle_count": len(rows),
        "rows": rows,
    }


