def upload_password() -> str:
    try:
        return str(st.secrets["UPLOAD_PASSWORD"])
    except Exception:
        return os.environ.get("UPLOAD_PASSWORD", "")


def money(value) -> str:
    if value is None or value == "" or (isinstance(value, float) and pd.isna(value)):
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return ""
    if pd.isna(number):
        return ""
    return f"{'-' if number < 0 else ''}${abs(number):,.2f}"


def as_frame(rows: list[dict], show_buyer: bool) -> pd.DataFrame:
    frame = pd.DataFrame(rows)
    rename = {
        "stock": "Stock",
        "vin": "VIN",
        "year": "Year",
        "make": "Make",
        "model": "Model",
        "trim": "Trim",
        "type": "Type",
        "mileage": "Mileage",
        "exterior": "Exterior",
        "interior": "Interior",
        "web_price": "Web Price",
        "purchase_cost": "Purchase Cost",
        "retail": "Retail Price",
        "age": "Age",
        "comm": "Comm Gross",
        "house": "House Gross",
        "finance": "Finance Gross",
        "sale_date": "Sale Date",
        "buyer": "Buyer",
        "salesperson": "Salesperson",
    }
    frame = frame.rename(columns=rename)
    keep = [
        "Stock",
        "VIN",
        "Year",
        "Make",
        "Model",
        "Trim",
        "Type",
        "Mileage",
        "Exterior",
        "Interior",
        "Web Price",
        "Purchase Cost",
        "Retail Price",
        "Age",
        "Comm Gross",
        "House Gross",
        "Finance Gross",
    ]
    if show_buyer:
        keep += ["Sale Date", "Buyer"]
    keep += ["Salesperson"]
    out = frame[[column for column in keep if column in frame.columns]].copy()
    if "Mileage" in out.columns:
        out["Mileage"] = pd.to_numeric(out["Mileage"], errors="coerce").round().astype("Int64")
    if "Year" in out.columns:
        out["Year"] = pd.to_numeric(out["Year"], errors="coerce").round().astype("Int64")
    return out


AVG_COLS = ["Mileage", "Web Price", "Purchase Cost", "Retail Price", "Age", "Comm Gross", "House Gross", "Finance Gross"]


def average_row(group: pd.DataFrame) -> dict:
    row = {column: None if column in ("Web Price", "Purchase Cost", "Retail Price", "Mileage", "Age", "Comm Gross", "House Gross", "Finance Gross") else "" for column in group.columns}
    row["Stock"] = "Average"
    for column in AVG_COLS:
        if column not in group.columns:
            continue
        values = pd.to_numeric(group[column], errors="coerce")
        row[column] = float(values.mean()) if values.notna().any() else None
    return row


def miles_text(value) -> str:
    if value is None or value == "" or (isinstance(value, float) and pd.isna(value)):
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return ""
    if pd.isna(number):
        return ""
    return f"{int(round(number)):,}"


def year_text(value) -> str:
    if value is None or value == "" or (isinstance(value, float) and pd.isna(value)):
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        text = str(value).strip()
        return "" if text.lower() in {"none", "nan"} else text
    if pd.isna(number):
        return ""
    return str(int(round(number)))


def week_label(payload: dict, prefix: str) -> str:
    source = str(payload.get("inventory_file") or "")
    name = source.split("/")[-1].strip()
    if name:
        return f"{prefix} · {name}"
    return f"{prefix} · {str(payload.get('saved_at') or '')[:10]}"


def age_text(value) -> str:
    if value is None or value == "" or (isinstance(value, float) and pd.isna(value)):
        return ""
    number = float(value)
    return f"{int(number)}" if number.is_integer() else f"{number:,.1f}"


def clear_filters():
    st.session_state["sold_search"] = ""
    st.session_state["sold_make"] = "All makes"
    st.session_state["sold_model"] = "All models"
    st.session_state["sold_match"] = "All vehicles"
    st.session_state["sold_person"] = "All salespeople"


def show_sheet(payload: dict):
    rows = payload.get("rows") or []
    if not rows:
        st.info("No list yet. The upload tab is where a new week gets published.")
        return
    rows = [{**row, "salesperson": salesperson_name(row.get("salesperson"))} for row in rows if row.get("row_kind") != "unmatched_sale"]

    bubble_slot = st.container()
    saved = str(payload.get("saved_at") or "").replace("T", " ")
    files = " · ".join(part for part in [payload.get("inventory_file"), payload.get("sales_file")] if part)
    st.caption(f"Saved {saved}" + (f" from {files}" if files else ""))

    left, make_col, model_col, person_col, right = st.columns([1.6, 1, 1, 1.4, 1.1])
    query = left.text_input("Search", placeholder="Stock, VIN, make, model, buyer, salesperson", key="sold_search")
    makes = ["All makes"] + sorted({row.get("make") or "" for row in rows if row.get("make")})
    make = make_col.selectbox("Make", makes, key="sold_make")
    model_rows = rows if make == "All makes" else [row for row in rows if row.get("make") == make]
    models = ["All models"] + sorted({str(row.get("model") or "").strip() for row in model_rows if str(row.get("model") or "").strip()})
    if st.session_state.get("sold_model") not in models:
        st.session_state["sold_model"] = "All models"
    model = model_col.selectbox("Model", models, key="sold_model")
    people = ["All salespeople"] + sorted({row.get("salesperson") or "" for row in rows if row.get("salesperson")})
    if st.session_state.get("sold_person") not in people:
        st.session_state["sold_person"] = "All salespeople"
    person = person_col.selectbox("Salesperson", people, key="sold_person")
    match = right.selectbox("Sales match", ["All vehicles", "Matched to a sale", "Not on sales report"], key="sold_match")
    right.button("Clear filters", on_click=clear_filters)
    show_buyer = st.checkbox("Buyer / sale date", value=True, key="show_buyer")
    frame = as_frame(rows, show_buyer)

    needle = query.strip().lower()
    if needle:
        blob = frame.astype(str).apply(lambda column: column.str.lower()).agg(" ".join, axis=1)
        frame = frame[blob.str.contains(needle, regex=False)]
    if make != "All makes":
        frame = frame[frame["Make"] == make]
    if model != "All models":
        frame = frame[frame["Model"] == model]
    if person != "All salespeople" and "Salesperson" in frame.columns:
        frame = frame[frame["Salesperson"] == person]
    if match == "Matched to a sale":
        frame = frame[frame["Stock"].isin({row["stock"] for row in rows if row.get("matched")})]
    elif match == "Not on sales report":
        frame = frame[frame["Stock"].isin({row["stock"] for row in rows if not row.get("matched")})]

    matched_count = int(pd.to_numeric(frame["Finance Gross"], errors="coerce").notna().sum()) if "Finance Gross" in frame.columns else 0
    with bubble_slot:
        c1, c2, c3, c4, c5, c6 = st.columns(6)
        c1.metric("Vehicles", f"{len(frame):,}")
        c2.metric("Makes", f"{frame['Make'].nunique():,}" if "Make" in frame.columns and not frame.empty else "0")
        c3.metric("Matched sales", f"{matched_count:,}")
        c4.metric("Comm gross", money(pd.to_numeric(frame["Comm Gross"], errors="coerce").sum() if "Comm Gross" in frame.columns else 0))
        c5.metric("House gross", money(pd.to_numeric(frame["House Gross"], errors="coerce").sum() if "House Gross" in frame.columns else 0))
        c6.metric("Finance gross", money(pd.to_numeric(frame["Finance Gross"], errors="coerce").sum() if "Finance Gross" in frame.columns else 0))
        miles_avg = pd.to_numeric(frame["Mileage"], errors="coerce").mean() if "Mileage" in frame.columns else None
        retail_avg = pd.to_numeric(frame["Retail Price"], errors="coerce").mean() if "Retail Price" in frame.columns else None
        age_avg = pd.to_numeric(frame["Age"], errors="coerce").mean() if "Age" in frame.columns else None
        comm_avg = pd.to_numeric(frame["Comm Gross"], errors="coerce").mean() if "Comm Gross" in frame.columns else None
        house_avg = pd.to_numeric(frame["House Gross"], errors="coerce").mean() if "House Gross" in frame.columns else None
        finance_avg = pd.to_numeric(frame["Finance Gross"], errors="coerce").mean() if "Finance Gross" in frame.columns else None
        a1, a2, a3, a4, a5, a6 = st.columns(6)
        a1.metric("Avg mileage", miles_text(miles_avg) or "—")
        a2.metric("Avg age", age_text(age_avg) or "—")
        a3.metric("Avg retail", money(retail_avg) or "—")
        a4.metric("Avg comm", money(comm_avg) or "—")
        a5.metric("Avg house", money(house_avg) or "—")
        a6.metric("Avg finance", money(finance_avg) or "—")
        if "Purchase Cost" in frame.columns and pd.to_numeric(frame["Purchase Cost"], errors="coerce").notna().any():
            cost_avg = pd.to_numeric(frame["Purchase Cost"], errors="coerce").mean()
            cost_total = pd.to_numeric(frame["Purchase Cost"], errors="coerce").sum()
            b1, b2 = st.columns(2)
            b1.metric("Purchase cost", money(cost_total) or "—")
            b2.metric("Avg purchase cost", money(cost_avg) or "—")

    web_avg = pd.to_numeric(frame["Web Price"], errors="coerce").mean() if "Web Price" in frame.columns else None
    web_txt = (money(web_avg) or "—").replace("$", "\\$")
    retail_txt = (money(retail_avg) or "—").replace("$", "\\$")
    comm_txt = (money(comm_avg) or "—").replace("$", "\\$")
    house_txt = (money(house_avg) or "—").replace("$", "\\$")
    finance_txt = (money(finance_avg) or "—").replace("$", "\\$")
    scope = " · ".join(part for part in [make if make != "All makes" else "", model if model != "All models" else "", person if person != "All salespeople" else ""] if part)
    st.caption(
        "Recap"
        + (f" · {scope}" if scope else "")
        + f" · {len(frame):,} vehicles · avg mileage {miles_text(miles_avg) or '—'} · avg web {web_txt} · avg retail {retail_txt} · avg age {age_text(age_avg) or '—'} · avg comm {comm_txt} · avg house {house_txt} · avg finance {finance_txt}"
    )

    money_cols = [column for column in ["Web Price", "Purchase Cost", "Retail Price", "Comm Gross", "House Gross", "Finance Gross"] if column in frame.columns]
    formats = {column: money for column in money_cols}
    if "Age" in frame.columns:
        formats["Age"] = age_text
    if "Mileage" in frame.columns:
        formats["Mileage"] = miles_text
    if "Year" in frame.columns:
        formats["Year"] = year_text

    def paint(value):
        if isinstance(value, (int, float)) and not isinstance(value, bool) and value < 0:
            return "color: #9b2c2c"
        return ""

    def emphasize(row):
        if row.get("Stock") == "Average":
            return ["font-weight: 700"] * len(row)
        return [""] * len(row)

    if frame.empty:
        st.info("Nothing matches that filter.")
    for make_name, group in frame.groupby("Make", sort=False):
        sold = int(group["Finance Gross"].notna().sum()) if "Finance Gross" in group.columns else 0
        retail_total = pd.to_numeric(group["Retail Price"], errors="coerce").sum() if "Retail Price" in group.columns else 0
        comm_total = pd.to_numeric(group["Comm Gross"], errors="coerce").sum() if "Comm Gross" in group.columns else 0
        house_total = pd.to_numeric(group["House Gross"], errors="coerce").sum() if "House Gross" in group.columns else 0
        finance_total = pd.to_numeric(group["Finance Gross"], errors="coerce").sum() if "Finance Gross" in group.columns else 0
        totals_parts = [("Retail", retail_total), ("Comm", comm_total), ("House", house_total), ("Finance", finance_total)]
        if "Purchase Cost" in group.columns and pd.to_numeric(group["Purchase Cost"], errors="coerce").notna().any():
            totals_parts.insert(0, ("Cost", pd.to_numeric(group["Purchase Cost"], errors="coerce").sum()))
        totals = " · ".join(
            f"{label} {(money(value) or '$0.00').replace('$', '&#36;')}"
            for label, value in totals_parts
        )
        st.markdown(
            f'<div class="make-bar">Make: {make_name} · Count: {len(group)}'
            + (f" · {sold} with sales" if sold else "")
            + f" · {totals}</div>",
            unsafe_allow_html=True,
        )
        shown = pd.concat([group, pd.DataFrame([average_row(group)])], ignore_index=True)
        styled = shown.style.format(formats, na_rep="").map(paint, subset=money_cols).apply(emphasize, axis=1)
        st.dataframe(styled, hide_index=True, use_container_width=True)

    st.download_button(
        "Download this view",
        data=frame.to_csv(index=False).encode(),
        file_name="super-helpful-sold-list.csv",
        mime="text/csv",
    )


def unmatched_tab():
    current = current_list()
    archives = archived_lists()
    choices = []
    if current:
        choices.append(current | {"label": week_label(current, "Current")})
    for sheet in archives:
        choices.append(sheet | {"label": week_label(sheet, "Archive")})
    if not choices:
        st.info("No list yet.")
        return
    picked = st.selectbox("Week", [item["label"] for item in choices], key="unmatched_week")
    payload = next(item for item in choices if item["label"] == picked)
    rows = [{**row, "salesperson": salesperson_name(row.get("salesperson"))} for row in payload.get("rows") or []]
    missing_sale = [row for row in rows if row.get("row_kind") != "unmatched_sale" and not row.get("matched")]
    missing_inventory = [row for row in rows if row.get("row_kind") == "unmatched_sale"]
    st.caption("Sold-list cars with no sales-report stock, and sales-report stocks that were not on the sold list. Older weeks only have the first group. New publishes keep both.")
    left, right = st.columns(2)
    left.metric("No sales report", f"{len(missing_sale):,}")
    right.metric("No sold-list stock", f"{len(missing_inventory):,}")
    st.markdown('<div class="make-bar">On the sold list, no matching sale</div>', unsafe_allow_html=True)
    if missing_sale:
        st.dataframe(as_frame(missing_sale, True), hide_index=True, use_container_width=True)
    else:
        st.info("Every sold-list stock in this week matched a sale.")
    st.markdown('<div class="make-bar">On the sales report, no sold-list stock</div>', unsafe_allow_html=True)
    if missing_inventory:
        st.dataframe(as_frame(missing_inventory, True), hide_index=True, use_container_width=True)
    elif any(row.get("row_kind") == "unmatched_sale" for row in rows):
        st.info("Every sales-report stock matched the sold list.")
    else:
        st.info("This week was saved before leftover sales were kept. Publish it again to capture sales that were not on the sold list.")


def list_tab():
    current = current_list()
    archives = archived_lists()
    choices = []
    if current:
        choices.append(("current", week_label(current, "Current")))
    for sheet in archives:
        choices.append((sheet["id"], week_label(sheet, "Archive")))
    if not choices:
        st.info("No list has been published yet.")
        return
    if len(choices) > 1:
        labels = [item[1] for item in choices]
        label = st.selectbox("Week", labels)
        picked = choices[labels.index(label)][0]
    else:
        picked = choices[0][0]
    payload = current if picked == "current" else next(sheet for sheet in archives if sheet["id"] == picked)
    show_sheet(payload)


def upload_tab():
    password = upload_password()
    if password:
        entered = st.text_input("Upload password", type="password")
        if entered != password:
            st.caption("This tab is just for publishing a new week. Everyone else can stay on Sold list.")
            if entered:
                st.error("Wrong password.")
            return
    else:
        st.warning("No upload password is set. Add UPLOAD_PASSWORD in Streamlit secrets before you share this app.")

    st.write("Inventory is the master file. The sales report replaces retail and adds commission, house, and finance gross.")
    inventory = st.file_uploader("Sold inventory", type=["csv", "xlsx", "xls"])
    sales = st.file_uploader("Vehicle sales report", type=["csv", "xlsx", "xls"])
    otc = st.file_uploader("OTC list, optional", type=["xlsx", "xls"])
    st.caption("The month summary uses the OTC sheet with that month's name, such as November 2026. Upload the OTC workbook when a month changes.")
    if st.button("Publish week", type="primary", disabled=not (inventory and sales)):
        try:
            rows, inventory_count, sales_count = rows_from_uploads(inventory.getvalue(), inventory.name, sales.getvalue(), sales.name)
            otc_saved = save_otc_upload(otc.getvalue(), otc.name) if otc else []
        except Exception as error:
            st.error(str(error))
            return
        had_current = current_list() is not None
        publish(rows, inventory.name, sales.name)
        matched = sum(1 for row in rows if row.get("matched"))
        extra = f" OTC months updated: {', '.join(otc_saved)}." if otc_saved else ""
        if had_current:
            st.success(f"Published {inventory_count} vehicles, {matched} matched to {sales_count} sales. The previous week is in the archive.{extra}")
        else:
            st.success(f"Published {inventory_count} vehicles, {matched} matched to {sales_count} sales.{extra}")
        st.rerun()


st.markdown(
    """
    <div class="app-title">Mega Super Helpful Sold List</div>
    <div class="app-rule"></div>
    <div class="app-sub">The cars that left, who sold them, and what they grossed.</div>
    """,
    unsafe_allow_html=True,
)
sold_tab, unmatched_tab_box, new_tab = st.tabs(["Sold list", "Unmatched", "Upload"])
with sold_tab:
    list_tab()
with unmatched_tab_box:
    unmatched_tab()
with new_tab:
    upload_tab()
